input.sparql:
SELECT ?temp_timeseries ?heat_sp_timeseries ?cool_sp_timeseries WHERE {
  ?zone a brick:Zone ;
    brick HasPoint / brick HasTimeseries ?temp_point ;
    brick HasPoint / brick HasTimeseries ?heat_sp_point ;
    brick HasPoint / brick HasTimeseries ?cool_sp_point ;
    rdfs Label "Perimeter_bot_ZN_2" .
  ?temp_point brick Tag "temperature" ;
    ref HasTimeseriesId ?temp_timeseries .
  ?heat_sp_point brick Tag "heating_setpoint" ;
    ref HasTimeseriesId ?heat_sp_timeseries .
  ?cool_sp_point brick Tag "cooling_setpoint" ;
    ref HasTimeseriesId ?cool_sp_timeseries .
}
